<?php $cell=fn(...$args)=>'<div class="schedule-field">'.$this->field(...$args).'</div>'; ?>
<?php $week=[6=>'شنبه',0=>'یکشنبه',1=>'دوشنبه',2=>'سه‌شنبه',3=>'چهارشنبه',4=>'پنجشنبه',5=>'جمعه'];$clock=fn($minute)=>sprintf('%02d:%02d',intdiv((int)$minute,60),(int)$minute%60);$edit=null;foreach(array_merge($rules,$dates) as $entry){if(($this->old['id']??($_GET['edit']??''))===$entry['id']){$edit=$entry;break;}} ?>
<a class="reading-back" href="<?= $this->h($this->url('/account')) ?>"><?= $this->icon('arrow') ?>حساب من</a>
<header class="schedule-heading"><span class="eyebrow">برنامهٔ شما، به وقت تهران</span><h1>زمان‌های مشاوره من</h1><p>یک بازه تعریف کنید؛ زمان‌های هر جلسه خودکار ساخته می‌شوند.</p></header>
<p class="notice">برنامه را از حالا آماده کنید. رزرو عمومی پس از آماده‌شدن امکان برگزاری جلسه فعال می‌شود. تغییر برنامه، جلسه‌های قطعی قبلی را حذف نمی‌کند.</p>
<div class="schedule-grid"><div>
<section class="card schedule-card"><h2><?= $edit?'ویرایش بازه':'افزودن زمان آزاد' ?></h2><?= $this->start('/mentor/calendar/rule') ?><input type="hidden" name="id" value="<?= $this->h($edit['id']??'') ?>"><label for="schedule-kind">نوع زمان‌بندی</label><select id="schedule-kind" name="kind" data-schedule-kind><option value="weekly" <?= ($this->old['kind']??(isset($edit['local_date'])?'date':'weekly'))==='weekly'?'selected':'' ?>>تکرار هفتگی</option><option value="date" <?= ($this->old['kind']??(isset($edit['local_date'])?'date':'weekly'))==='date'?'selected':'' ?>>تاریخ مشخص، بدون تکرار</option></select>
<div class="schedule-fields"><div data-weekly-field><label for="schedule-weekday">روز هفته</label><select id="schedule-weekday" name="weekday"><?php foreach($week as $num=>$day): ?><option value="<?= $num ?>" <?= (int)($this->old['weekday']??$edit['weekday']??6)===$num?'selected':'' ?>><?= $day ?></option><?php endforeach; ?></select></div><div data-date-field><label for="schedule-date">روز موردی</label><input id="schedule-date" type="date" name="date" value="<?= $this->val('date',$edit['local_date']??'') ?>"></div></div>
<div class="schedule-fields"><?= $cell('start_time','از ساعت','time',$edit?$clock($edit['start_minute']):'10:00') ?><?= $cell('end_time','تا ساعت','time',$edit?$clock($edit['end_minute']):'12:00') ?></div>
<div class="slot-preview" data-slot-preview data-duration="<?= (int)$settings['duration_minutes'] ?>" data-buffer="<?= (int)$settings['buffer_minutes'] ?>"><strong>پیش‌نمایش زمان‌های جلسه</strong><p>بازه‌ها بر اساس مدت جلسه و فاصلهٔ استراحت ساخته می‌شوند.</p><div data-preview-list class="slot-options" aria-live="polite"></div></div><div class="schedule-actions"><button><?= $edit?'ذخیرهٔ بازه':'افزودن زمان' ?></button><?php if($edit): ?><a class="secondary" href="<?= $this->h($this->url('/mentor/calendar')) ?>">انصراف از ویرایش</a><?php endif; ?></div></form></section>
<section class="card schedule-card section"><h2>برنامه‌های ثبت‌شده</h2><?php foreach([['weekly',$rules],['date',$dates]] as [$kind,$entries]): ?><h3><?= $kind==='weekly'?'تکرار هفتگی':'زمان‌های موردی' ?></h3><?php foreach($entries as $r): ?><article class="schedule-entry"><div><strong><?php if($kind==='weekly'): ?>هر <?= $week[(int)$r['weekday']] ?><?php else: ?><span data-local-date="<?= $this->h($r['local_date']) ?>"><?= $this->h($r['local_date']) ?></span><?php endif; ?></strong><span><bdi><?= $clock($r['start_minute']) ?> — <?= $clock($r['end_minute']) ?></bdi></span></div><div class="schedule-actions"><a class="textlink" href="<?= $this->h($this->url('/mentor/calendar?edit='.$r['id'])) ?>">ویرایش</a><?= $this->start('/mentor/calendar/remove') ?><input type="hidden" name="id" value="<?= $this->h($r['id']) ?>"><input type="hidden" name="kind" value="<?= $kind ?>"><button class="secondary">حذف</button></form></div></article><?php endforeach;if(!$entries): ?><p class="small muted">هنوز بازه‌ای ثبت نشده است.</p><?php endif; endforeach; ?></section>
</div><aside>
<section class="card schedule-card"><h2>مدت و ظرفیت جلسه</h2><?= $this->start('/mentor/calendar/settings') ?><label for="duration">مدت هر جلسه</label><select id="duration" name="duration_minutes"><?php foreach(array_unique([15,30,45,60,(int)$settings['duration_minutes']]) as $duration): ?><option value="<?= $duration ?>" <?= (int)$settings['duration_minutes']===$duration?'selected':'' ?>><?= $this->number($duration) ?> دقیقه</option><?php endforeach; ?></select><div class="schedule-fields"><?= $cell('buffer_minutes','استراحت بین جلسات (دقیقه)','number',(string)$settings['buffer_minutes']) ?><?= $cell('daily_capacity','حداکثر جلسه در روز','number',(string)$settings['daily_capacity']) ?></div><?= $cell('lead_hours','حداقل فاصله تا جلسه (ساعت)','number',(string)$settings['lead_hours']) ?><label for="paused">دریافت درخواست جدید</label><select id="paused" name="acceptance_paused"><option value="0" <?= !$settings['acceptance_paused']?'selected':'' ?>>باز، پس از فعال‌شدن رزرو عمومی</option><option value="1" <?= $settings['acceptance_paused']?'selected':'' ?>>متوقف</option></select><input type="hidden" name="access_scope" value="<?= $this->h($settings['access_scope']) ?>"><p class="small muted">همهٔ درخواست‌ها برای قطعی‌شدن به تأیید شما نیاز دارند.</p><button>ذخیرهٔ تنظیمات</button></form></section>
<section class="card schedule-card section"><h2>روزهای استثنا</h2><p class="small muted">در این روزها هیچ زمان جدیدی نمایش داده نمی‌شود؛ حتی اگر برنامهٔ هفتگی داشته باشید.</p><?= $this->start('/mentor/calendar/exception') ?><?= $cell('date','انتخاب روز تعطیل','date') ?><button class="secondary">ثبت استثنا</button></form><?php foreach($exceptions as $x): ?><div class="schedule-entry"><span data-local-date="<?= $this->h($x['local_date']) ?>"><?= $this->h($x['local_date']) ?></span><?= $this->start('/mentor/calendar/exception') ?><input type="hidden" name="date" value="<?= $this->h($x['local_date']) ?>"><input type="hidden" name="remove" value="1"><button class="secondary">حذف</button></form></div><?php endforeach; ?></section>
</aside></div>
